1	package shadow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"math/big"
7		"testing"
8		"time"
9	)
10	
11	// 本文件通过公开入口（UpdateDesired/Report 写入，Diff/Get/Audit 查询及重开）
12	// 回归保障配置差异查询中“数字按数值比较”的现有行为：
13	// 真实数值差别（包括超过 float64 精度的大整数与高精度小数）必须列出，
14	// 仅仅写法不同的等值数字不算差异，数字与字符串不做类型自动转换；
15	// 查询结果保留双方提交的完整数字原文，且查询本身不改写任何已保存状态。
16	
17	// seedDeviceConfigs 登记新设备并分别写入期望配置与上报配置，
18	// 使后续测试可以直接通过 Diff 观察双方比较结果。
19	func seedDeviceConfigs(t *testing.T, s *Store, id, desired, reported string) {
20		t.Helper()
21		mustRegister(t, s, id, "1.0")
22		if _, err := s.UpdateDesired(id, "op", base, 0, json.RawMessage(desired)); err != nil {
23			t.Fatalf("UpdateDesired(%s): %v", id, err)
24		}
25		if err := s.Report(id, 1, base.Add(time.Minute), "1.0", json.RawMessage(reported)); err != nil {
26			t.Fatalf("Report(%s): %v", id, err)
27		}
28	}
29	
30	// decodeJSONNumber 把一段 JSON 标量解码为 json.Number，
31	// 确保差异里返回的数字仍是 JSON 数字，而不是字符串或近似后的浮点值。
32	func decodeJSONNumber(t *testing.T, raw json.RawMessage) json.Number {
33		t.Helper()
34		dec := json.NewDecoder(bytes.NewReader(raw))
35		dec.UseNumber()
36		var v any
37		if err := dec.Decode(&v); err != nil {
38			t.Fatalf("decode %q: %v", raw, err)
39		}
40		n, ok := v.(json.Number)
41		if !ok {
42			t.Fatalf("value %s decoded as %T, want JSON number", raw, v)
43		}
44		return n
45	}
46	
47	func mustRat(t *testing.T, literal string) *big.Rat {
48		t.Helper()
49		r, ok := new(big.Rat).SetString(literal)
50		if !ok {
51			t.Fatalf("test premise: %q is not parseable as an exact number", literal)
52		}
53		return r
54	}
55	
56	// 超过 float64 安全整数范围的相邻大整数、超出 float64 小数精度的高精度小数
57	// 必须被识别为真实差异；嵌套对象里只列实际不同的字段，数组整体比较只列数组
58	// 所在路径（不展开下标）。返回值保留提交时的完整数字，双方存在性均为真。
59	func TestDiffDistinguishesLargeAndHighPrecisionNumbers(t *testing.T) {
60		s, _ := openTemp(t)
61		cases := []struct {
62			name         string
63			id           string
64			desired      string
65			reported     string
66			path         string
67			wantDesired  string
68			wantReported string
69			// wholeValue 表示该路径差异的双方值是数组等整体值，
70			// 不应按 JSON 数字标量解码；同时用于核对数组不拆下标。
71			wholeValue bool
72		}{
73			{
74				name:         "adjacent integers beyond float64 safe range",
75				id:           "dev-bigint",
76				desired:      `{"x":9007199254740992}`,
77				reported:     `{"x":9007199254740993}`,
78				path:         "/x",
79				wantDesired:  "9007199254740992",
80				wantReported: "9007199254740993",
81			},
82			{
83				name:         "high precision decimals distinct past float64 precision",
84				id:           "dev-decimal",
85				desired:      `{"x":0.10000000000000000001}`,
86				reported:     `{"x":0.10000000000000000002}`,
87				path:         "/x",
88				wantDesired:  "0.10000000000000000001",
89				wantReported: "0.10000000000000000002",
90			},
91			{
92				name:         "large integers inside nested object",
93				id:           "dev-nested-bigint",
94				desired:      `{"o":{"x":9007199254740992}}`,
95				reported:     `{"o":{"x":9007199254740993}}`,
96				path:         "/o/x",
97				wantDesired:  "9007199254740992",
98				wantReported: "9007199254740993",
99			},
100			{
101				name:         "high precision decimals inside nested object",
102				id:           "dev-nested-decimal",
103				desired:      `{"o":{"y":0.10000000000000000001}}`,
104				reported:     `{"o":{"y":0.10000000000000000002}}`,
105				path:         "/o/y",
106				wantDesired:  "0.10000000000000000001",
107				wantReported: "0.10000000000000000002",
108			},
109			{
110				name:         "signed values genuinely different",
111				id:           "dev-signed",
112				desired:      `{"x":-1}`,
113				reported:     `{"x":1}`,
114				path:         "/x",
115				wantDesired:  "-1",
116				wantReported: "1",
117			},
118			{
119				name:         "signed small decimals genuinely different",
120				id:           "dev-signed-decimal",
121				desired:      `{"x":-0.0001}`,
122				reported:     `{"x":0.0001}`,
123				path:         "/x",
124				wantDesired:  "-0.0001",
125				wantReported: "0.0001",
126			},
127			{
128				name:         "large integers inside array compared as whole array",
129				id:           "dev-array-bigint",
130				desired:      `{"xs":[9007199254740992]}`,
131				reported:     `{"xs":[9007199254740993]}`,
132				path:         "/xs",
133				wantDesired:  "[9007199254740992]",
134				wantReported: "[9007199254740993]",
135				wholeValue:   true,
136			},
137			{
138				name:         "high precision decimals inside array compared as whole array",
139				id:           "dev-array-decimal",
140				desired:      `{"xs":[0.10000000000000000001]}`,
141				reported:     `{"xs":[0.10000000000000000002]}`,
142				path:         "/xs",
143				wantDesired:  "[0.10000000000000000001]",
144				wantReported: "[0.10000000000000000002]",
145				wholeValue:   true,
146			},
147			{
148				name:         "array nested in object keeps only array path",
149				id:           "dev-nested-array",
150				desired:      `{"o":{"xs":[9007199254740992,1]}}`,
151				reported:     `{"o":{"xs":[9007199254740993,1]}}`,
152				path:         "/o/xs",
153				wantDesired:  "[9007199254740992,1]",
154				wantReported: "[9007199254740993,1]",
155				wholeValue:   true,
156			},
157		}
158		for _, tc := range cases {
159			t.Run(tc.name, func(t *testing.T) {
160				seedDeviceConfigs(t, s, tc.id, tc.desired, tc.reported)
161				entries, err := s.Diff(tc.id)
162				if err != nil {
163					t.Fatalf("Diff: %v", err)
164				}
165				// 每对配置只在指定路径存在一处差异；数组用例借此证明
166				// 不会把 /xs/0 之类下标展开成额外差异。
167				if len(entries) != 1 {
168					t.Fatalf("want exactly one diff at %s, got %+v", tc.path, entries)
169				}
170				e := entries[0]
171				if e.Path != tc.path {
172					t.Fatalf("path: want %s, got %s", tc.path, e.Path)
173				}
174				if !e.DesiredExists || !e.ReportedExists {
175					t.Fatalf("both sides must exist: %+v", e)
176				}
177				if string(e.Desired) != tc.wantDesired {
178					t.Fatalf("desired value: want %s, got %s", tc.wantDesired, e.Desired)
179				}
180				if string(e.Reported) != tc.wantReported {
181					t.Fatalf("reported value: want %s, got %s", tc.wantReported, e.Reported)
182				}
183				if tc.wholeValue {
184					return
185				}
186				// 标量数字：差异值必须仍是 JSON 数字且逐字保留提交内容，
187				// 不能被近似成另一个数字或转成字符串。
188				dn := decodeJSONNumber(t, e.Desired)
189				rn := decodeJSONNumber(t, e.Reported)
190				if dn.String() != tc.wantDesired || rn.String() != tc.wantReported {
191					t.Fatalf("numbers not preserved verbatim: %s vs %s", dn, rn)
192				}
193				// 确认测试前提：两侧确实是不同的精确数值。
194				if mustRat(t, tc.wantDesired).Cmp(mustRat(t, tc.wantReported)) == 0 {
195					t.Fatalf("test premise broken: %s and %s are numerically equal", tc.wantDesired, tc.wantReported)
196				}
197			})
198		}
199	}
200	
201	// 同一数值的整数、小数、科学计数法写法（含正负零、嵌套对象与数组元素、
202	// 对象字段换序与 JSON 空白变化）必须判为配置一致，不产生任何差异。
203	func TestDiffTreatsNumericSpellingsAsEqual(t *testing.T) {
204		s, _ := openTemp(t)
205		cases := []struct {
206			name     string
207			id       string
208			desired  string
209			reported string
210		}{
211			{"integer vs decimal", "dev-eq-1", `{"x":1000}`, `{"x":1000.00}`},
212			{"integer vs scientific", "dev-eq-2", `{"x":1000}`, `{"x":1e3}`},
213			{"decimal vs scientific", "dev-eq-3", `{"x":1000.00}`, `{"x":1e3}`},
214			{"scientific on desired side", "dev-eq-4", `{"x":1e3}`, `{"x":1000}`},
215			{"small decimal vs scientific", "dev-eq-5", `{"x":0.0001}`, `{"x":1e-4}`},
216			{"large integer vs exact scientific spelling", "dev-eq-6", `{"x":9007199254740992}`, `{"x":9.007199254740992e15}`},
217			{"positive zero vs negative zero", "dev-eq-7", `{"x":0}`, `{"x":-0}`},
218			{"negative zero decimal forms", "dev-eq-8", `{"x":-0.0}`, `{"x":0.0e0}`},
219			{"numeric forms inside nested object", "dev-eq-9", `{"o":{"x":1000,"y":0.0001}}`, `{"o":{"x":1e3,"y":1e-4}}`},
220			{"numeric forms as array elements", "dev-eq-10", `{"xs":[1000,0.0001]}`, `{"xs":[1.0e3,1e-4]}`},
221			{"integer vs decimal array element", "dev-eq-11", `{"xs":[1000]}`, `{"xs":[1000.00]}`},
222			{"field reorder whitespace and numeric forms", "dev-eq-12",
223				"{\n  \"a\": 1000,\n  \"b\": 0.0001\n}", `{"b":1e-4,"a":1e3}`},
224			{"whitespace around compact number", "dev-eq-13", `{ "x": 1000 }`, `{"x":1e3}`},
225		}
226		for _, tc := range cases {
227			t.Run(tc.name, func(t *testing.T) {
228				seedDeviceConfigs(t, s, tc.id, tc.desired, tc.reported)
229				entries, err := s.Diff(tc.id)
230				if err != nil {
231					t.Fatalf("Diff: %v", err)
232				}
233				if len(entries) != 0 {
234					t.Fatalf("numeric spellings must compare equal, got diffs: %+v", entries)
235				}
236			})
237		}
238	}
239	
240	// 数字与写着相同字符的字符串属于不同类型：必须保留差异且不自动转换类型。
241	func TestDiffDoesNotCoerceNumberAndString(t *testing.T) {
242		s, _ := openTemp(t)
243	
244		seedDeviceConfigs(t, s, "dev-typestr", `{"x":1000}`, `{"x":"1000"}`)
245		entries, err := s.Diff("dev-typestr")
246		if err != nil {
247			t.Fatal(err)
248		}
249		if len(entries) != 1 || entries[0].Path != "/x" {
250			t.Fatalf("want single /x diff, got %+v", entries)
251		}
252		e := entries[0]
253		if !e.DesiredExists || !e.ReportedExists {
254			t.Fatalf("both sides must exist: %+v", e)
255		}
256		if string(e.Desired) != "1000" {
257			t.Fatalf("desired number: %s", e.Desired)
258		}
259		if string(e.Reported) != `"1000"` {
260			t.Fatalf("reported string must keep quotes: %s", e.Reported)
261		}
262		if n := decodeJSONNumber(t, e.Desired); n.String() != "1000" {
263			t.Fatalf("desired should be JSON number: %s", n)
264		}
265		var str string
266		if err := json.Unmarshal(e.Reported, &str); err != nil || str != "1000" {
267			t.Fatalf("reported should be JSON string \"1000\": %v %q", err, str)
268		}
269	
270		// 数组内元素类型不同：数组整体比较，只列数组路径。
271		seedDeviceConfigs(t, s, "dev-typestr-arr", `{"xs":[1000]}`, `{"xs":["1000"]}`)
272		entries, err = s.Diff("dev-typestr-arr")
273		if err != nil {
274			t.Fatal(err)
275		}
276		if len(entries) != 1 || entries[0].Path != "/xs" {
277			t.Fatalf("want whole-array diff /xs, got %+v", entries)
278		}
279		if string(entries[0].Desired) != "[1000]" || string(entries[0].Reported) != `["1000"]` {
280			t.Fatalf("array values: %s vs %s", entries[0].Desired, entries[0].Reported)
281		}
282	}
283	
284	// 等值数字与不等值数字同时存在时，结果只包含实际不同的路径，按 JSON Pointer
285	// 字典序返回，且每条差异中的双方值与对应字段精确匹配。
286	func TestDiffMixedEqualAndUnequalNumbers(t *testing.T) {
287		s, _ := openTemp(t)
288		desired := `{"same":1000,"big":9007199254740992,"deep":{"eq":0.0001,"neq":0.10000000000000000001},"arr":[1,2],"kind":1}`
289		reported := `{"same":1e3,"big":9007199254740993,"deep":{"eq":1e-4,"neq":0.10000000000000000002},"arr":[1,2,3],"kind":"1"}`
290		seedDeviceConfigs(t, s, "dev-mix", desired, reported)
291	
292		entries, err := s.Diff("dev-mix")
293		if err != nil {
294			t.Fatal(err)
295		}
296		// /same 与 /deep/eq 仅数字写法不同，不应出现。
297		want := []struct {
298			path     string
299			desired  string
300			reported string
301		}{
302			{"/arr", "[1,2]", "[1,2,3]"},
303			{"/big", "9007199254740992", "9007199254740993"},
304			{"/deep/neq", "0.10000000000000000001", "0.10000000000000000002"},
305			{"/kind", "1", `"1"`},
306		}
307		if len(entries) != len(want) {
308			t.Fatalf("want %d diffs, got %+v", len(want), entries)
309		}
310		for i := range entries {
311			if i > 0 && entries[i-1].Path >= entries[i].Path {
312				t.Fatalf("paths not strictly lexicographic: %q then %q", entries[i-1].Path, entries[i].Path)
313			}
314			if entries[i].Path != want[i].path {
315				t.Fatalf("entry %d path: want %s, got %s", i, want[i].path, entries[i].Path)
316			}
317			if !entries[i].DesiredExists || !entries[i].ReportedExists {
318				t.Fatalf("%s existence flags: %+v", entries[i].Path, entries[i])
319			}
320			if string(entries[i].Desired) != want[i].desired {
321				t.Fatalf("%s desired: want %s, got %s", entries[i].Path, want[i].desired, entries[i].Desired)
322			}
323			if string(entries[i].Reported) != want[i].reported {
324				t.Fatalf("%s reported: want %s, got %s", entries[i].Path, want[i].reported, entries[i].Reported)
325			}
326		}
327	}
328	
329	// Diff/Get/Audit 都是只读查询：不得改写设备保存的期望配置或上报配置，
330	// 不得增加修订号或审计记录；再次读取仍看到原先提交的完整数字。
331	// 返回给调用方的数据被篡改也不影响存储与后续查询。
332	func TestDiffNumericQueriesAreReadOnly(t *testing.T) {
333		s, _ := openTemp(t)
334		desiredCfg := `{"big":9007199254740992,"frac":0.10000000000000000001,"same":1000}`
335		reportedCfg := `{"big":9007199254740993,"frac":0.10000000000000000002,"same":1e3}`
336		seedDeviceConfigs(t, s, "dev-ro", desiredCfg, reportedCfg)
337	
338		before, err := s.Get("dev-ro")
339		if err != nil {
340			t.Fatal(err)
341		}
342		if before.Revision != 1 || before.LastSeq != 1 {
343			t.Fatalf("unexpected starting state: %+v", before)
344		}
345	
346		first, err := s.Diff("dev-ro")
347		if err != nil {
348			t.Fatal(err)
349		}
350		if len(first) != 2 || first[0].Path != "/big" || first[1].Path != "/frac" {
351			t.Fatalf("initial diffs: %+v", first)
352		}
353		// 重复查询结果一致。
354		again, err := s.Diff("dev-ro")
355		if err != nil || len(again) != 2 {
356			t.Fatalf("second Diff: %v %+v", err, again)
357		}
358		recs, err := s.Audit("dev-ro")
359		if err != nil {
360			t.Fatal(err)
361		}
362		if len(recs) != 1 {
363			t.Fatalf("audit must not grow from queries: %+v", recs)
364		}
365	
366		after, err := s.Get("dev-ro")
367		if err != nil {
368			t.Fatal(err)
369		}
370		if after.Revision != before.Revision || after.LastSeq != before.LastSeq {
371			t.Fatalf("revision/seq changed by queries: before %+v after %+v", before, after)
372		}
373		if string(after.Desired) != desiredCfg {
374			t.Fatalf("desired config rewritten by queries: %s", after.Desired)
375		}
376		if string(after.Reported) != reportedCfg {
377			t.Fatalf("reported config rewritten by queries: %s", after.Reported)
378		}
379		if string(recs[0].Before) != "{}" || string(recs[0].After) != desiredCfg {
380			t.Fatalf("audit configs altered: before=%s after=%s", recs[0].Before, recs[0].After)
381		}
382	
383		// 篡改查询返回值后，存储内容与后续查询不受影响。
384		first[0].Desired[0] = '0'
385		first[1].Reported[0] = '0'
386		again[0].Desired = nil
387		after.Desired[0] = 'X'
388		after.Reported[0] = 'X'
389		final, err := s.Get("dev-ro")
390		if err != nil {
391			t.Fatal(err)
392		}
393		if string(final.Desired) != desiredCfg || string(final.Reported) != reportedCfg {
394			t.Fatalf("stored configs mutated by caller: %s / %s", final.Desired, final.Reported)
395		}
396		if final.Revision != 1 || final.LastSeq != 1 {
397			t.Fatalf("state changed by caller mutation: %+v", final)
398		}
399		diffs, err := s.Diff("dev-ro")
400		if err != nil {
401			t.Fatal(err)
402		}
403		if len(diffs) != 2 || string(diffs[0].Desired) != "9007199254740992" ||
404			string(diffs[1].Reported) != "0.10000000000000000002" {
405			t.Fatalf("diff results mutated by caller: %+v", diffs)
406		}
407	}
