409	// 关闭重开后数字比较行为与完整数字原文保持不变：真实差异仍按完整数字列出，
410	// 仅写法不同的等值数字不会在打开时重算差异，且双方配置、修订号与审计保持原样。
411	func TestDiffNumericBehaviorSurvivesReopen(t *testing.T) {
412		s, dir := openTemp(t)
413		desiredCfg := `{"big":9007199254740992,"frac":0.10000000000000000001,"same":1000}`
414		reportedCfg := `{"big":9007199254740993,"frac":0.10000000000000000002,"same":1e3}`
415		seedDeviceConfigs(t, s, "dev-persist", desiredCfg, reportedCfg)
416		// 另一台设备只有等值写法差异：重开重算差异后仍应为零条。
417		seedDeviceConfigs(t, s, "dev-equal", `{"x":1000}`, `{"x":1e3}`)
418		if entries, _ := s.Diff("dev-equal"); len(entries) != 0 {
419			t.Fatalf("precondition: equal spellings diff: %+v", entries)
420		}
421		if err := s.Close(); err != nil {
422			t.Fatal(err)
423		}
424	
425		s2, err := Open(dir)
426		if err != nil {
427			t.Fatalf("reopen: %v", err)
428		}
429		defer s2.Close()
430	
431		v, err := s2.Get("dev-persist")
432		if err != nil {
433			t.Fatal(err)
434		}
435		if string(v.Desired) != desiredCfg || string(v.Reported) != reportedCfg {
436			t.Fatalf("full digits lost across reopen: %s / %s", v.Desired, v.Reported)
437		}
438		if v.Revision != 1 || v.LastSeq != 1 {
439			t.Fatalf("revision/seq changed across reopen: %+v", v)
440		}
441		entries, err := s2.Diff("dev-persist")
442		if err != nil {
443			t.Fatal(err)
444		}
445		if len(entries) != 2 {
446			t.Fatalf("want /big and /frac, got %+v", entries)
447		}
448		want := []struct {
449			path     string
450			desired  string
451			reported string
452		}{
453			{"/big", "9007199254740992", "9007199254740993"},
454			{"/frac", "0.10000000000000000001", "0.10000000000000000002"},
455		}
456		for i, w := range want {
457			if entries[i].Path != w.path || !entries[i].DesiredExists || !entries[i].ReportedExists {
458				t.Fatalf("entry %d flags/path: %+v", i, entries[i])
459			}
460			if string(entries[i].Desired) != w.desired || string(entries[i].Reported) != w.reported {
461				t.Fatalf("entry %d values: %s / %s", i, entries[i].Desired, entries[i].Reported)
462			}
463		}
464		if recs, _ := s2.Audit("dev-persist"); len(recs) != 1 || string(recs[0].After) != desiredCfg {
465			t.Fatalf("audit changed across reopen: %+v", recs)
466		}
467	
468		equalEntries, err := s2.Diff("dev-equal")
469		if err != nil {
470			t.Fatal(err)
471		}
472		if len(equalEntries) != 0 {
473			t.Fatalf("equal numeric spellings must stay equal after reopen: %+v", equalEntries)
474		}
