package shadow

import (
	"encoding/json"
	"errors"
	"testing"
	"time"
)

// 本文件通过公开入口（Register/UpdateDesired/Report 写入，Diff/Get/Audit 查询）
// 回归保障同一字段在对象与普通值之间反复切换时，差异路径与首次出现时间的
// 现有行为：
//   - 双方同为对象时逐层比较，只在实际不同的子路径列差异；
