		{Path: "/wifi/ssid", DesiredExists: true, ReportedExists: true,
			Desired: json.RawMessage(`"home"`), Reported: json.RawMessage(`"cafe"`), Since: t1},
	})

	// 第二次上报：wifi 整体变成字符串。期望侧仍是对象，但不再下钻：
	// 只在 /wifi 列一条整体差异，双方都存在，分别返回期望对象与上报字符串；
